export function createStudioUI({state,esc,btn,field,openDialog,formDialog,api,endpoint,refresh}) {
  const title = code => ({blocked_missing_brand_assets:'Materiais oficiais pendentes',blocked_higgsfield_not_configured:'Higgsfield não configurado',blocked_higgsfield_executor_unvalidated:'Executor ainda não validado',blocked_production_review_required:'Decisões de produção pendentes'}[code]||'Produção pendente');
  function summary() {
    return (state().production||[]).map(p=>`<section class="notice-box studio-production-summary"><strong>${esc(title(p.state))}</strong><p>A entrega existente aguarda as dependências de produção. Veja o que falta e como continuar.</p>${btn('Ver produção existente','studio-production',`data-id="${esc(p.contentId)}"`,'secondary')}</section>`).join('');
  }
  function detail(p) {
    const c=state().records.content.find(c=>c.id===p.contentId);
    const explain=p.blockers.map(b=>`<section class="notice-box"><strong>${esc(title(b.code))}</strong><p>${esc(b.message)}</p>${(b.missing||[]).map(m=>`<p><strong>${esc(m.material)}</strong><br>${esc(m.why)}<br>${esc(m.where)}</p>`).join('')}</section>`).join('');
    openDialog('Produção visual · '+c.title,`<div class="studio-production-detail"><p class="dialog-explainer">Esta é a mesma entrega do Estúdio. A verificação local registra dependências; gerar uma imagem exige uma ação explícita e um executor validado.</p><dl class="publication-facts">${[['Estado',title(p.state)],['Entrega existente','Versão '+p.sourceVersion],['Verificação registrada',p.storedVersion?'Versão '+p.storedVersion:'Ainda não registrada'],['Executor','API Higgsfield · '+(p.executor.state==='not_configured'?'não configurada':'validação pendente')],['Geração','Não iniciada'],['Arquivo final','Não produzido'],['Formato solicitado','Uma imagem · 1080 × 1080 · PNG ou JPG'],['Aprovação humana','Não solicitada; não há peça final']].map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${p.stale?'<p class="operation-blocker">O conteúdo mudou depois da verificação. Atualize o diagnóstico; a versão anterior continua no histórico.</p>':''}${explain}<details class="operation-details"><summary>Briefing preservado e especificação</summary><h3>Objetivo</h3><p>${esc(p.specification.objective)}</p><h3>Público</h3><p>${esc(p.specification.audience||'Não informado')}</p><h3>Texto de origem · ainda requer confirmação final</h3><p class="prewrap">${esc(p.specification.exactText.source.replace(/\\n/g,'\n'))}</p><h3>Direção visual de origem</h3><p class="prewrap">${esc((p.specification.artDirection||'').replace(/\\n/g,'\n'))}</p><h3>Critérios de aprovação</h3><ul>${p.specification.approvalCriteria.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p>Margens, área segura e texto final ainda precisam ser definidos na especificação de produção. Nenhuma revisão técnica, factual ou visual de uma peça final foi realizada.</p></details><details class="operation-details"><summary>Origem e rastreabilidade</summary><p>Execução criativa: ${esc(p.sourceJobId||'Origem não vinculada')}</p><p>Campanha: ${esc(p.campaignId||'Nenhuma campanha vinculada na entrega original')}</p><p>Hash do briefing, não da imagem: <code>${esc(p.sourceHash)}</code></p></details><div class="detail-actions">${btn('Registrar verificação','studio-check',`data-id="${esc(p.contentId)}"`)}${btn('Materiais oficiais','studio-materials','','secondary')}<a class="p-button secondary" href="#/integrations" data-action="close-dialog">Configurar Higgsfield</a></div></div>`,true);
  }
  function materials() {
    const s=state(),m=s.brandMaterials||{},org=s.company.id;
    const images=s.assets.filter(a=>a.mime.startsWith('image/')),fonts=s.assets.filter(a=>a.mime.startsWith('font/'));
    formDialog('Materiais oficiais · '+s.company.name,`<p class="dialog-explainer wide">Use os arquivos oficiais desta empresa. Se faltarem arquivos, feche esta janela e use Enviar arquivo no Estúdio. O logo aceita PNG, JPEG ou WebP; a fonte aceita WOFF2, TTF ou OTF.</p>`+field('logoAssetId','Versão oficial do logo','select',m.logoAssetId||'',[['','Selecione o arquivo'],...images.map(a=>[a.id,a.name])],true)+field('fontAssetId','Arquivo da fonte oficial','select',m.fontAssetId||'',[['','Selecione a fonte'],...fonts.map(a=>[a.id,a.name])],true)+field('fontFamily','Família da fonte','text',m.fontFamily||'',[],true)+field('background','Cor de fundo · #RRGGBB','text',m.colors?.background||'',[],true)+field('foreground','Cor do texto · #RRGGBB','text',m.colors?.foreground||'',[],true)+field('accent','Cor de destaque · #RRGGBB','text',m.colors?.accent||'',[],true)+field('confirmed','Confirmo que os arquivos e as cores são os materiais oficiais aprovados desta empresa.','checkbox',false),async d=>{
      if(state().company.id!==org)throw new Error('A empresa ativa mudou. Confira os materiais novamente.');
      await api(endpoint('studio/materials'),'POST',{logoAssetId:d.logoAssetId,fontAssetId:d.fontAssetId,fontFamily:d.fontFamily,colors:{background:d.background,foreground:d.foreground,accent:d.accent},confirmed:d.confirmed===true});
      await refresh(false);
    },'Salvar materiais oficiais',true);
  }
  return {summary,detail,materials};
}
